#define HELM_RING_HUB_H       108
/** @brief 模式名半径（12/3/6/9 点）。墨迹内缘 ≈83，离指针最外墨迹 ≈10px。 */
#define HELM_RING_LAB_R       99
/** @brief 模式名标签盒宽（居中，模拟器同为 40）。 */
#define HELM_RING_LAB_W       40
#define HELM_RING_PTR_R0      52
#define HELM_RING_PTR_R1      72
#define HELM_RING_PTR_CROSS   8
#define HELM_RING_TICK_RIN_M  58  /* 整点刻度内端（66*140/160） */
#define HELM_RING_TICK_RIN_m  60  /* 其余刻度内端（69*140/160） */
#define HELM_RING_TICK_ROUT   65  /* 刻度外端（74*140/160） */
#define HELM_RING_WEEK_Y      224
#define HELM_RING_BAR_BASE    260
#define HELM_RING_BAR_W       8
#define HELM_RING_BAR_GAP     12
#define HELM_RING_ANIM_MS     160

/** @brief 四模式名（顺序 = 扇区方位：0 上、1 右、2 下、3 左）。 */
static const char * const s_ring_names[4] = {
    "骑行", "导航", "记录", "设置"
};
/** @brief 盘心描述行（只描述模式内容，不写按键引导）。 */
static const char * const s_ring_descs[4] = {
    "上次骑行", "转向提示", "数据回顾", "设备设置"
};

/* 旋转动效的瞬态状态（对象级的 0/1 两套扇区弧做交叉淡入）。 */
static int32_t s_ring_anim_v;
static uint8_t s_ring_slot;             /**< 当前扇区在 ring_fill[] 的槽位。 */
static uint8_t s_ring_fill_base[2];     /**< 各槽最终不透明度（设置模式 20%）。 */
static uint8_t s_ring_fa0, s_ring_fb1;  /**< 本段动画两端填充不透明度。 */
static int32_t s_ring_ang0;
static int32_t s_ring_ang1;
static int s_ring_to_mode;
static bool s_ring_swapped;

static int helm_ring_norm(int a)
{
    a %= 360;
    return (a < 0) ? (a + 360) : a;
}

/** @brief trig(±32767) × r，四舍五入（不用 libm，板端与模拟器同一算法）。 */
static int helm_ring_trig(int32_t v, int r)
{
    int64_t p = (int64_t)v * r;

    if (p >= 0) {
        return (int)((p + 16384) / 32767);
    }
    return (int)((p - 16384) / 32767);
}

/** @brief 角度（0 = 12 点，顺时针）→ 页面根坐标。 */
static void helm_ring_pt(int angle, int r, int * x, int * y)
{
    int a = helm_ring_norm(angle);

    *x = HELM_RING_CX + helm_ring_trig(lv_trigo_sin((int16_t)a), r);
    *y = HELM_RING_CY - helm_ring_trig(lv_trigo_cos((int16_t)a), r);
}

/** @brief 模式身份色：骑行=ok、导航=BAN_NAV（蓝）、记录=NAV（橙）、设置=mute。
 *  @note 板端 `HELM_COLOR_NAV` 是橙色强调色；导航身份必须用横幅那支蓝
 *        （`HELM_COLOR_BAN_NAV`），否则罗盘上导航与记录同色、分不出来。 */
static uint32_t helm_ring_ink_hex(int mode)
{
    switch (mode & 3) {
    case 0:
        return HELM_COLOR_OK;
    case 1:
        return HELM_COLOR_BAN_NAV;
    case 2:
        return HELM_COLOR_NAV;
    default:
        return HELM_COLOR_MUTE;
    }
}

/** @brief 扇区 12px 浅色填充。设置没有专属 fill ⇒ 同色 20% 透明度。 */
static uint32_t helm_ring_fill_hex(int mode)
{
    switch (mode & 3) {
    case 0:
        return HELM_COLOR_OK_FILL;
    case 1:
        return HELM_COLOR_BAN_NAV_FILL;
    case 2:
        return HELM_COLOR_NAV_FILL;
    default:
        return HELM_COLOR_MUTE;
    }
}

static helm_icon_t helm_ring_icon_id(int mode)
{
    switch (mode & 3) {
    case 0:
        return HELM_ICON_BIKE;
    case 1:
        return HELM_ICON_NAV;
    case 2:
        return HELM_ICON_RECORD;
    default:
        return HELM_ICON_SETTINGS;
    }
}

/** @brief 30px 模式名（板端没有 30px 点阵档；正常固件走系统 TTF，工厂回退 22px）。 */
static const lv_font_t * helm_ring_name_font(void)
{
    return helm_font_sys(30, s_sh.font_val);
}

static void helm_ring_set_font(lv_obj_t * obj, const lv_font_t * font)
{
    if (obj != NULL && font != NULL &&
        lv_obj_get_style_text_font(obj, 0) != font) {
        lv_obj_set_style_text_font(obj, font, 0);
    }
}

static void helm_ring_set_arc_opa(lv_obj_t * arc, int opa)
{
    if (arc == NULL) {
        return;
    }
    if (opa < 0) {
        opa = 0;
    } else if (opa > 255) {
        opa = 255;
    }
    lv_obj_set_style_arc_opa(arc, (lv_opa_t)opa, LV_PART_INDICATOR);
}

/**
 * @brief 一段扇区弧（只画 indicator；主弧全透明）。
 * @param mode  0..3：角度 = mode*90−90±26（上/右/下/左）。
 * @param width 12 = 浅色填充，2 = 深色外沿。
 */
static lv_obj_t * helm_ring_arc_make(lv_obj_t * parent, int mode, int width,
                                     uint32_t hex, lv_opa_t opa)
{
    lv_obj_t * arc = lv_arc_create(parent);
    int a = (mode & 3) * 90 - 90;

    lv_obj_set_size(arc, HELM_RING_D, HELM_RING_D);
    lv_obj_set_pos(arc, HELM_RING_CX - HELM_RING_D / 2,
                   HELM_RING_CY - HELM_RING_D / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    /* 主弧不画，只留 indicator 扇段。 */
    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);
    lv_obj_set_style_arc_opa(arc, opa, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, width, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, helm_color(hex), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
    lv_arc_set_rotation(arc, 0);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 100);
    lv_arc_set_bg_angles(arc, (lv_value_precise_t)helm_ring_norm(a - 26),
                         (lv_value_precise_t)helm_ring_norm(a + 26));
    return arc;
}

/** @brief 建一套扇区（浅色填充 + 2px 深色外沿）到指定槽位。 */
static void helm_ring_sector_make(uint8_t slot, int mode)
{
    uint8_t base = ((mode & 3) == 3) ? (uint8_t)LV_OPA_20
                                     : (uint8_t)LV_OPA_COVER;

    s_ring_fill_base[slot] = base;
    s_sh.ring_fill[slot] = helm_ring_arc_make(s_sh.ring, mode, 12,
                                             helm_ring_fill_hex(mode),
                                             (lv_opa_t)base);
    s_sh.ring_trk[slot] = helm_ring_arc_make(s_sh.ring, mode, 2,
                                            helm_ring_ink_hex(mode),
                                            LV_OPA_COVER);
}

/** @brief 24 刻度：整点 3px（INK）、其余 1px（MUTE）。 */
static void helm_ring_build_ticks(lv_obj_t * parent)
{
    int i;

    for (i = 0; i < 24; i++) {
        const int deg = i * 15;
        const bool major = (i % 6) == 0;
        const int th = major ? 3 : 1;
        int x1, y1, x2, y2;
        int x, y, w, h;
        lv_obj_t * box;

        helm_ring_pt(deg, major ? HELM_RING_TICK_RIN_M : HELM_RING_TICK_RIN_m,
                     &x1, &y1);
        helm_ring_pt(deg, HELM_RING_TICK_ROUT, &x2, &y2);
        if (LV_ABS(x2 - x1) >= LV_ABS(y2 - y1)) {
            x = (x1 < x2) ? x1 : x2;
            y = y1;
            w = LV_ABS(x2 - x1) + 1;
            h = th;
        } else {
            x = x1;
            y = (y1 < y2) ? y1 : y2;
            w = th;
            h = LV_ABS(y2 - y1) + 1;
        }

        box = lv_obj_create(parent);
        lv_obj_remove_style_all(box);
        lv_obj_set_pos(box, x, y);
        lv_obj_set_size(box, w, h);
        lv_obj_set_style_bg_color(box,
            helm_color(major ? HELM_COLOR_INK : HELM_COLOR_MUTE), 0);
        lv_obj_set_style_bg_opa(box, LV_OPA_COVER, 0);
        lv_obj_set_style_radius(box, th / 2, 0);
        lv_obj_remove_flag(box, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);
        s_sh.ring_tick[i] = box;
    }
}

/** @brief 指针：中心 → r=72 的杆 + 末端 8px 横杆。 */
static void helm_ring_pointer_layout(int32_t angle)
{
    const int a = helm_ring_norm((int)angle);
    const int32_t sn = lv_trigo_sin((int16_t)a);
    const int32_t cs = lv_trigo_cos((int16_t)a);
    const int sx = (int)sn;
    const int sy = (int)(-cs);
    const int px = (int)cs;
    const int py = (int)sn;
    const int x0 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R0);
    const int y0 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R0);
    const int x1 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R1);
    const int y1 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R1);

    s_sh.ring_ptr_pts[0].x = x0;
    s_sh.ring_ptr_pts[0].y = y0;
    s_sh.ring_ptr_pts[1].x = x1;
    s_sh.ring_ptr_pts[1].y = y1;
    s_sh.ring_cross_pts[0].x =
        x1 - helm_ring_trig(px, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[0].y =
        y1 - helm_ring_trig(py, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[1].x =
        x1 + helm_ring_trig(px, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[1].y =
        y1 + helm_ring_trig(py, HELM_RING_PTR_CROSS);
    if (s_sh.ring_ptr != NULL) {
        lv_line_set_points(s_sh.ring_ptr, s_sh.ring_ptr_pts, 2);
    }
    if (s_sh.ring_cross != NULL) {
        lv_line_set_points(s_sh.ring_cross, s_sh.ring_cross_pts, 2);
    }
}

/** @brief 标题行：名字 160 宽居中；20px 图标贴在文字墨迹左侧（同模拟器）。 */
static void helm_ring_title_layout(void)
{
    const lv_font_t * nf = helm_ring_name_font();
    lv_point_t sz;
    int left;

    if (s_sh.ring_name == NULL) {
        return;
    }
    lv_text_get_size(&sz, lv_label_get_text(s_sh.ring_name), nf, 0, 0,
                     LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    left = HELM_RING_HUB_W / 2 - (int)sz.x / 2;
    lv_obj_set_pos(s_sh.ring_name, 0, 0);
    if (s_sh.ring_icon != NULL) {
        lv_obj_set_pos(s_sh.ring_icon, left - 2 - 20, 19 - 10);
    }
}

/** @brief 主值按 hub 中线居中；单位挂在右侧、与主值共用基线。 */
static void helm_ring_value_layout(const char * txt, bool has_unit,
                                   const char * unit)
{
    const lv_font_t * vf = s_sh.font_val;
    const lv_font_t * uf = s_sh.font_lab;
    lv_point_t sz;
    int vx;

    if (s_sh.ring_value == NULL) {
        return;
    }
    lv_text_get_size(&sz, txt, vf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    vx = HELM_RING_HUB_W / 2 - (int)sz.x / 2;
    lv_obj_set_pos(s_sh.ring_value, vx, 55);

    if (s_sh.ring_unit == NULL) {
        return;
    }
    if (!has_unit) {
        helm_show(s_sh.ring_unit, false);
        return;
    }

    {
        const int vb = lv_font_get_line_height(vf) - vf->base_line;
        const int ub = lv_font_get_line_height(uf) - uf->base_line;

        lv_obj_set_pos(s_sh.ring_unit, vx + (int)sz.x + 3, 55 + vb - ub);
    }
    helm_label_set(s_sh.ring_unit, unit);
    helm_show(s_sh.ring_unit, true);
}

/** @brief 四个模式名：选中 = 模式色 + 15px，其余 = mute + 12px。 */
static void helm_ring_paint_labels(int mode)
{
    int i;

    for (i = 0; i < 4; i++) {
        const bool sel = (i == (mode & 3));

        helm_ring_set_font(s_sh.ring_lab[i],
                           sel ? s_sh.font_title : s_sh.font_lab);
        helm_set_text_hex(s_sh.ring_lab[i],
                          sel ? helm_ring_ink_hex(mode) : HELM_COLOR_MUTE);
    }
}

/** @brief 换模式：名字/描述/图标/四方位标签（不动数值那一组）。 */
static void helm_ring_paint_mode(int mode)
{
    mode &= 3;
    s_sh.ring_mode = (uint8_t)mode;
    if (s_sh.ring_name == NULL) {
        return;
    }

    helm_ring_set_font(s_sh.ring_name, helm_ring_name_font());
    helm_label_set(s_sh.ring_name, s_ring_names[mode]);
    helm_set_text_hex(s_sh.ring_name, HELM_COLOR_INK);
    helm_ring_title_layout();

    if (s_sh.ring_icon != NULL) {
        hfi_set(s_sh.ring_icon, helm_ring_icon_id(mode));
        lv_obj_set_style_text_color(s_sh.ring_icon,
                                    helm_color(helm_ring_ink_hex(mode)), 0);
    }
    helm_label_set(s_sh.ring_desc, s_ring_descs[mode]);
    helm_set_text_hex(s_sh.ring_desc, HELM_COLOR_MUTE);
    helm_ring_paint_labels(mode);
}

