/* ═══════════════════════════════════════════════════════════════════════════
 * 环形主页（HELM_PAGE_RING，WP-HELM10/R1-S2）
 *
 * 几何 1:1 搬模拟器 `lvgl_sim/src/scene_helm.c` 的 `dial_build()`，**只减状态栏
 * 24px**（页面根从屏幕 y=24 开始）：
 *   环心 (120,114)、直径 140；hub (40,60,160,108)；周统计 y=224、柱底 y=260。
 * 数据全部取真实来源（bicycle_runtime / map_page / myvendor_*），不搬模拟器的
 * `s_recs[]/s_week[]` 假数据。
 *
 * 旋转动效只动指针/两套扇区弧/盘心文字，**不做整屏 transform 或整屏重绘**：
 * 弧对象 140×140，指针是 2 点折线，文字只在 50% 处换一次。
 * ═══════════════════════════════════════════════════════════════════════════ */

#define HELM_RING_CX          120
#define HELM_RING_CY          114
#define HELM_RING_D           140
#define HELM_RING_HUB_X       40
#define HELM_RING_HUB_Y       60
#define HELM_RING_HUB_W       160
#define HELM_RING_HUB_H       108
/** @brief 模式名半径（12/3/6/9 点）。墨迹内缘 ≈83，离指针最外墨迹 ≈10px。 */
#define HELM_RING_LAB_R       99
/** @brief 模式名标签盒宽（居中，模拟器同为 40）。 */
#define HELM_RING_LAB_W       40
#define HELM_RING_PTR_R0      52
#define HELM_RING_PTR_R1      72
#define HELM_RING_PTR_CROSS   8
#define HELM_RING_TICK_RIN_M  58  /* 整点刻度内端（66*140/160） */
#define HELM_RING_TICK_RIN_m  60  /* 其余刻度内端（69*140/160） */
#define HELM_RING_TICK_ROUT   65  /* 刻度外端（74*140/160） */
#define HELM_RING_WEEK_Y      224
#define HELM_RING_BAR_BASE    260
#define HELM_RING_BAR_W       8
#define HELM_RING_BAR_GAP     12
#define HELM_RING_ANIM_MS     160

/** @brief 四模式名（顺序 = 扇区方位：0 上、1 右、2 下、3 左）。 */
static const char * const s_ring_names[4] = {
    "骑行", "导航", "记录", "设置"
};
/** @brief 盘心描述行（只描述模式内容，不写按键引导）。 */
static const char * const s_ring_descs[4] = {
    "上次骑行", "转向提示", "数据回顾", "设备设置"
};

/* 旋转动效的瞬态状态（对象级的 0/1 两套扇区弧做交叉淡入）。 */
static int32_t s_ring_anim_v;
static uint8_t s_ring_slot;             /**< 当前扇区在 ring_fill[] 的槽位。 */
static uint8_t s_ring_fill_base[2];     /**< 各槽最终不透明度（设置模式 20%）。 */
static uint8_t s_ring_fa0, s_ring_fb1;  /**< 本段动画两端填充不透明度。 */
static int32_t s_ring_ang0;
static int32_t s_ring_ang1;
static int s_ring_to_mode;
static bool s_ring_swapped;

=== 8560-8720
 * @brief 盘下统计行。
 * @details **缺口**：GPX 列表/周聚合在 `helm_menu.c` 里是私有表（本包只被允许
 *          新增 `helm_menu_open_at()`），helm_shell 拿不到"本周里程 / 次数 /
 *          最近日期" ⇒ 按任务允许的降级：显示"上次骑行 X km · 记录数未知"，
 *          7 根迷你柱保持隐藏（不自造内存周数据）。见 S2/NOTES.md。
 */
static void helm_ring_week_sync(void)
{
    char buf[64];

    if (s_sh.ring_week == NULL) {
        return;
    }
    if (s_sh.last_km > 0.05f) {
        char km[16];

        helm_fmt_km(km, sizeof(km), s_sh.last_km);
        /* 记录条数/周聚合要扫 GPX 目录（菜单私有表），本阶段拿不到就只报
         * 上次里程；写「记录数未知」比留空更难看，宁可不写。 */
        lv_snprintf(buf, sizeof(buf), "上次骑行 %s km", km);
    } else {
        lv_snprintf(buf, sizeof(buf), "暂无骑行记录");
    }
    helm_label_set(s_sh.ring_week, buf);
    helm_set_text_hex(s_sh.ring_week, HELM_COLOR_INK);
}

/** @brief 盘心数值 + 副行（每 500ms 刷新；只改文本与水平居中）。 */
static void helm_ring_paint_values(const bicycle_runtime_t * rt)
{
    char v[24];
    char u[8];
    char sub[64];
    char km[16];
    bool has_unit = false;
    const int mode = s_sh.ring_mode & 3;

    v[0] = '\0';
    u[0] = '\0';
    sub[0] = '\0';

    switch (mode) {
    case 0:
        /* 骑行：上次骑行里程（来源 = shell 既有的 last_km，即
         * myvendor_devctl_last_ride_m_get / 保存骑行时回写）。 */
        if (s_sh.last_km > 0.05f) {
            helm_fmt_km(km, sizeof(km), s_sh.last_km);
        } else {
            lv_snprintf(km, sizeof(km), "0.0");
        }
        lv_snprintf(v, sizeof(v), "%s", km);
        lv_snprintf(u, sizeof(u), "km");
        has_unit = true;
        if (helm_riding()) {
            char sp[16];

            helm_fmt_speed(sp, sizeof(sp), helm_session_avg_kph(rt));
            lv_snprintf(sub, sizeof(sub), "均速 %s km/h", sp);
        } else {
            /* 描述行已经是「上次骑行」，副行再写一遍就是重复。 */
            lv_snprintf(sub, sizeof(sub), "未开始骑行");
        }
        break;

    case 1:
        if (s_sh.map != NULL && map_page_nav_active(s_sh.map)) {
            double rem = map_page_nav_remain_m(s_sh.map);
            double tot = map_page_nav_total_m(s_sh.map);
            char tk[16];

            if (rem < 0.0) {
                rem = 0.0;
            }
            if (tot < 0.0) {
                tot = 0.0;
            }
            helm_fmt_km(km, sizeof(km), (float)(rem / 1000.0));
            helm_fmt_km(tk, sizeof(tk), (float)(tot / 1000.0));
            lv_snprintf(v, sizeof(v), "%s", km);
            lv_snprintf(u, sizeof(u), "km");
            has_unit = true;
            lv_snprintf(sub, sizeof(sub), "全程 %s km", tk);
        } else {
            lv_snprintf(v, sizeof(v), "--");
            lv_snprintf(sub, sizeof(sub), "未在导航");
        }
        break;

    case 2:
        /* 记录：拿不到 GPX 条数/最近日期 ⇒ 显示上次记录里程，副行"暂无"。 */
        if (s_sh.last_km > 0.05f) {
            helm_fmt_km(km, sizeof(km), s_sh.last_km);
        } else {
            lv_snprintf(km, sizeof(km), "0.0");
        }
        lv_snprintf(v, sizeof(v), "%s", km);
        lv_snprintf(u, sizeof(u), "km");
        has_unit = true;
        lv_snprintf(sub, sizeof(sub), "暂无记录日期");
        break;

    default: {
        int pct = myvendor_sys_battery_percent();
        const char * ver = myvendor_sw_version();

        if (pct < 0) {
            pct = 0;
        } else if (pct > 100) {
            pct = 100;
        }
        lv_snprintf(v, sizeof(v), "%d", pct);
        lv_snprintf(u, sizeof(u), "%%");
        has_unit = true;
        if (ver != NULL && ver[0] != '\0') {
            lv_snprintf(sub, sizeof(sub), "固件 %s", ver);
        } else {
            lv_snprintf(sub, sizeof(sub), "固件 --");
        }
        break;
    }
    }

    helm_label_set(s_sh.ring_value, v);
    helm_set_text_hex(s_sh.ring_value, HELM_COLOR_INK);
    helm_ring_value_layout(v, has_unit, u);
    helm_label_set(s_sh.ring_sub, sub);
    helm_set_text_hex(s_sh.ring_sub, HELM_COLOR_MUTE);
    helm_ring_week_sync();
}

static void helm_ring_paint_all(void)
{
    helm_ring_paint_mode(s_sh.ring_mode & 3);
    helm_ring_paint_values(bicycle_runtime_get());
}

/** @brief 500ms 节拍：旋转中不刷（交叉淡入与数值换行抢同一帧会抖）。 */
static void helm_ring_tick(const bicycle_runtime_t * rt)
{
    if (s_sh.ring == NULL || s_sh.ring_busy) {
        return;
    }
    /* 系统 TTF 可能比首帧晚就绪：字体换了就按新字宽重排标题行，
     * 否则 30px 名字会一直停在开机时的 22px 回退档。 */
    if (s_sh.ring_name != NULL &&
        lv_obj_get_style_text_font(s_sh.ring_name, 0) != helm_ring_name_font()) {
        helm_ring_paint_mode(s_sh.ring_mode);
    }
    helm_ring_paint_values(rt);
}

static void helm_ring_anim_exec(void * var, int32_t p)
{
    int fa, fb, ta, tb;

    LV_UNUSED(var);
    if (!s_sh.ring_busy || helm_anim_is_suspended()) {
        return;
    }

    s_sh.ring_angle = s_ring_ang0 + (s_ring_ang1 - s_ring_ang0) * p / 1000;

    s_sh.ring_angle = s_ring_ang0 + (s_ring_ang1 - s_ring_ang0) * p / 1000;
    helm_ring_pointer_layout(s_sh.ring_angle);

    fa = (int)s_ring_fa0 * (1000 - (int)p) / 1000;
    fb = (int)s_ring_fb1 * (int)p / 1000;
    ta = 255 * (1000 - (int)p) / 1000;
    tb = 255 * (int)p / 1000;
    helm_ring_set_arc_opa(s_sh.ring_fill[s_ring_slot], fa);
    helm_ring_set_arc_opa(s_sh.ring_trk[s_ring_slot], ta);
    helm_ring_set_arc_opa(s_sh.ring_fill[s_ring_slot ^ 1u], fb);
    helm_ring_set_arc_opa(s_sh.ring_trk[s_ring_slot ^ 1u], tb);

    if (!s_ring_swapped && p >= 500) {
        s_ring_swapped = true;
        helm_ring_paint_mode(s_ring_to_mode);
        helm_ring_paint_values(bicycle_runtime_get());
    }
}

/** @brief 把旋转收尾到目标态（动画完成 / 被覆盖取消共用）。 */
static void helm_ring_anim_finish(void)
{
    const uint8_t slot = s_ring_slot;
    const uint8_t nslot = (uint8_t)(slot ^ 1u);

    if (s_sh.ring_fill[slot] != NULL) {
        lv_obj_delete(s_sh.ring_fill[slot]);
        s_sh.ring_fill[slot] = NULL;
    }
    if (s_sh.ring_trk[slot] != NULL) {
        lv_obj_delete(s_sh.ring_trk[slot]);
        s_sh.ring_trk[slot] = NULL;
    }
    s_ring_slot = nslot;
    helm_ring_set_arc_opa(s_sh.ring_fill[nslot], s_ring_fill_base[nslot]);
    helm_ring_set_arc_opa(s_sh.ring_trk[nslot], 255);
    s_sh.ring_angle = s_ring_ang1;
    s_sh.ring_busy = false;
    helm_ring_pointer_layout(s_sh.ring_angle);
    helm_ring_paint_mode(s_ring_to_mode);
    helm_ring_paint_values(bicycle_runtime_get());
    printf("helm: ring rotate done mode=%d angle=%d\n",
           (int)s_sh.ring_mode, (int)helm_ring_norm((int)s_sh.ring_angle));
}

static void helm_ring_anim_done(lv_anim_t * a)
{
    LV_UNUSED(a);
    if (s_sh.ring_busy) {
        helm_ring_anim_finish();
    }
}

static void helm_ring_anim_cancel(void)
{
    if (!s_sh.ring_busy) {
        return;
    }
    lv_anim_delete(&s_ring_anim_v, helm_ring_anim_exec);
    helm_ring_anim_finish();
}

/**
 * @brief 环转一格。
 * @param dir +1 顺时针（KEY2 短）、−1 逆时针（KEY1 短）。
 * @details 160ms；只失效 pointer 折线、两套 140×140 扇区弧和盘心两块文字。
 *          旋转中再次按键**丢弃**（板上 100~200ms/帧，叠加动画只会更卡）。
 */
static void helm_ring_rotate(int dir)
{
    int from;
    int to;
    int32_t a0;
    int32_t target;
    uint8_t slot;
    uint8_t nslot;
    lv_anim_t a;

    if (!s_sh.attached || s_sh.ring == NULL ||
        s_sh.view_id != HELM_PAGE_RING) {
        return;
    }
    if (s_sh.ring_busy) {
        printf("helm: ring rotate busy, drop\n");
        return;
    }
    if (dir == 0) {
        dir = 1;
    }

    from = s_sh.ring_mode & 3;
    to = (from + ((dir > 0) ? 1 : 3)) & 3;
    a0 = s_sh.ring_angle;
    target = (int32_t)to * 90;
    if (dir > 0) {
        while (target <= a0) {
            target += 360;
        }
    } else {
        while (target >= a0) {
            target -= 360;
        }
    }

    slot = s_ring_slot;
    nslot = (uint8_t)(slot ^ 1u);
    if (s_sh.ring_fill[nslot] != NULL) {
        lv_obj_delete(s_sh.ring_fill[nslot]);
        s_sh.ring_fill[nslot] = NULL;
    }
    if (s_sh.ring_trk[nslot] != NULL) {
        lv_obj_delete(s_sh.ring_trk[nslot]);
        s_sh.ring_trk[nslot] = NULL;
    }
    helm_ring_sector_make(nslot, to);
    /* 新扇区从 0 起步：建完立刻按 0 拨下去（sector_make 给了最终值）。 */
    helm_ring_set_arc_opa(s_sh.ring_fill[nslot], 0);
    helm_ring_set_arc_opa(s_sh.ring_trk[nslot], 0);

    s_ring_fa0 = s_ring_fill_base[slot];
    s_ring_fb1 = s_ring_fill_base[nslot];
    s_ring_ang0 = a0;
    s_ring_ang1 = target;
    s_ring_to_mode = to;
    s_ring_swapped = false;
    s_sh.ring_busy = true;

    printf("helm: ring rotate %s mode=%d->%d angle=%d->%d\n",
           (dir > 0) ? "cw" : "ccw", from, to, (int)a0, (int)target);

    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_ring_anim_v);
    lv_anim_set_values(&a, 0, 1000);
    lv_anim_set_duration(&a, HELM_RING_ANIM_MS);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
    lv_anim_set_exec_cb(&a, helm_ring_anim_exec);
    lv_anim_set_completed_cb(&a, helm_ring_anim_done);
    lv_anim_start(&a);
}

/**
 * @brief 进入当前模式。
 * @details 骑行 → 先开始/继续记录，再落到骑行页（DATA）；
 *          导航/记录/设置 → 菜单根行（0 / 4 / 6，0 基）。
 */
static void helm_ring_enter(int mode)
{
    switch (mode & 3) {
    case 0:
        /* 真按键进场：先解锁演示页，否则开始骑行后 apply_view 仍停在 RING。 */
        if (s_demo_page != (helm_page_id_t)0xff) {
            s_demo_page = (helm_page_id_t)0xff;
        }
        /* R1-S4a：环形→骑行清掉"停在环形"标志（暂停中也一样：ensure_ride 恢复）。 */
        s_sh.at_ring = false;
        helm_shell_ensure_ride();
        if (helm_riding()) {
            if (!helm_nav_on()) {
                s_sh.ride_idx = 0;
            }
            helm_apply_view();
            helm_refresh_numbers();
        }
        break;
    case 1:
        if (helm_menu_open_at(0) != 0) {
            printf("helm: ring menu(nav) open failed\n");
        }
        break;
    case 2:
        if (helm_menu_open_at(4) != 0) {
            printf("helm: ring menu(rides) open failed\n");
        }
        break;
    default:
        if (helm_menu_open_at(6) != 0) {
            printf("helm: ring menu(settings) open failed\n");
        }
        break;
    }
}

/**
 * @brief 搭建环形主页（挂在 MAP 页根，不新增 lv_pm 页）。
 * @details 全部绝对定位（父对象不设 flex）：几何与模拟器逐项对应。
 */
static void helm_build_ring(lv_obj_t * root)
{
    lv_obj_t * p;
    lv_obj_t * hair;
    int i;

    /* 换主题重建：旧对象和进行中的旋转动画一并作废（对象已随页面删掉）。 */
    lv_anim_delete(&s_ring_anim_v, helm_ring_anim_exec);
    s_sh.ring_busy = false;

    s_sh.ring = lv_obj_create(root);
    lv_obj_remove_style_all(s_sh.ring);
    helm_style_paper(s_sh.ring);
    lv_obj_set_style_bg_opa(s_sh.ring, LV_OPA_COVER, 0);
    lv_obj_set_size(s_sh.ring, PAGE_HOR_RES, HELM_PAGE_H);
    lv_obj_set_pos(s_sh.ring, 0, 0);
    lv_obj_add_flag(s_sh.ring, LV_OBJ_FLAG_FLOATING);
    lv_obj_add_flag(s_sh.ring, LV_OBJ_FLAG_HIDDEN);
    lv_obj_clear_flag(s_sh.ring, LV_OBJ_FLAG_CLICKABLE);

    /* 外圈 2px track（模拟器 d2_ring 是 2px 描边圆，不是 arc）。 */
    p = lv_obj_create(s_sh.ring);
    lv_obj_remove_style_all(p);
