                             HELM_COLOR_MUTE, "");
    lv_obj_set_pos(s_sh.ring_sub, 0, 92);
    lv_obj_set_width(s_sh.ring_sub, HELM_RING_HUB_W);
    lv_obj_set_style_text_align(s_sh.ring_sub, LV_TEXT_ALIGN_CENTER, 0);
    lv_label_set_long_mode(s_sh.ring_sub, LV_LABEL_LONG_MODE_CLIP);

    /* 四个模式名：12/3/6/9 点，标签盒 40 宽居中（半径 99）。 */
    {
        static const int lx[4] = { 0, 1, 0, -1 };
        static const int ly[4] = { -1, 0, 1, 0 };

        for (i = 0; i < 4; i++) {
