            lv_label_set_long_mode(s_sh.ring_lab[i], LV_LABEL_LONG_MODE_CLIP);
        }
    }

    /* 盘下：一行统计 + 7 根迷你柱（柱底 y=260、宽 8、间距 12）。 */
    s_sh.ring_week = helm_lab(s_sh.ring, s_sh.font_lab, HELM_COLOR_INK, "");
    lv_obj_set_pos(s_sh.ring_week, 0, HELM_RING_WEEK_Y);
    lv_obj_set_width(s_sh.ring_week, PAGE_HOR_RES);
