        lv_obj_set_style_radius(bar, 1, 0);
        lv_obj_remove_flag(bar, LV_OBJ_FLAG_CLICKABLE);
        /* 拿不到 GPX 周数据 ⇒ 先隐藏（不自造内存周数据）。 */
        lv_obj_add_flag(bar, LV_OBJ_FLAG_HIDDEN);
        s_sh.ring_bar[i] = bar;
    }

    s_sh.ring_angle = (int32_t)(s_sh.ring_mode & 3) * 90;
    helm_ring_pointer_layout(s_sh.ring_angle);
    helm_ring_paint_all();
}

