    lv_obj_remove_flag(s_sh.rotbar, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(s_sh.rotbar, LV_OBJ_FLAG_OVERFLOW_VISIBLE);

    helm_label_set(s_sh.save_done_title, saved ? "已保存" : "未保存");
    helm_label_set(s_sh.save_done_hint,
                   saved ? "记录已写入本机" : "本次数据未写入");

    helm_fmt_hms(buf, sizeof(buf), s_ride_sum.ms);
    helm_label_set(s_sh.save_done_time, buf);

    helm_fmt_km(buf, sizeof(buf), s_ride_sum.km);
    lv_snprintf(line, sizeof(line), "%s km", buf);
    helm_label_set(s_sh.save_done_dist, line);

    helm_fmt_speed(buf, sizeof(buf), s_ride_sum.avg);
    helm_label_set(s_sh.save_done_avg, buf);

    s_sh.save_done_open = true;
