    lv_obj_move_foreground(s_sh.save_done_mask);
    /* 第一段落库时 `helm_finish_ride()` 还会弹一条 2 s 的系统通知（已保存 + 文件名）。
     * 第二段卡片就是最终答复，等宽横幅会压住卡头 ⇒ 收掉横幅（只影响展示）。 */
    lv_pm_notify_dismiss();
    helm_obj_stagger_in(s_sh.save_done_mask);
    printf("helm: save stage2 saved=%d dist=%.1f km t=%.1f min avg=%.1f km/h\n",
           saved ? 1 : 0, (double)s_ride_sum.km,
           (double)((float)s_ride_sum.ms / 60000.0f), (double)s_ride_sum.avg);
}

/** @brief 第二段关闭：只收卡片并回环形（记录已在第一段结束）。 */
static void helm_save_done_close(void)
{
    if (!s_sh.save_done_open) {
        return;
    }

    s_sh.save_done_open = false;
    if (s_sh.save_done_mask != NULL) {
        lv_obj_add_flag(s_sh.save_done_mask, LV_OBJ_FLAG_HIDDEN);
    }

    printf("helm: save stage2 closed -> ring\n");
    myvendor_sound_back();
    helm_back_to_ring();
}

static bool helm_arrive_open(void)
{
    return s_sh.arrive_dock && !lv_obj_has_flag(s_sh.arrive_dock, LV_OBJ_FLAG_HIDDEN);
}

static void helm_arrive_hide(void)
{
    s_sh.arrive_dismissed = true;
    if (s_sh.arrive_dock) {
        lv_obj_add_flag(s_sh.arrive_dock, LV_OBJ_FLAG_HIDDEN);
    }
}

static void helm_arrive_confirm(void)
{
    helm_arrive_hide();
#if VMAP_ROUTE_ENABLE
    map_page_nav_stop(s_sh.map);
#endif
}

static void helm_on_prev(void * ud)
{
    uint8_t n = helm_page_count();
    uint8_t * idx;
#if MYVENDOR_LVGL_STALL_LOG
    uint32_t t0;
#endif

    LV_UNUSED(ud);
    if (!s_sh.attached) {
        LVGL_STALL("helm_on_prev drop !attached covered=%d",
            (int)s_sh.ui_covered);
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    /* 第二段结果卡（R1-S4b）：只留「右=关闭」，左键无动作。 */
    if (helm_save_done_active()) {
        printf("helm: save stage2 open, KEY1 short ignored\n");
        return;
    }

    /* 环形主页（R1-S2）：短按 = 逆时针转一格，**不翻页**（旧页留给 S3 再摘）。
     * 必须在演示锁解锁之前分流：环形页的演示态也要能连续转。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY1 short rotate ccw (mode=%u)\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_rotate(-1);
        return;
    }

    /* 演示页面锁：任意翻页键先解锁，本次按键继续走正常翻页（下面会 apply）。 */
    if (s_demo_page != (helm_page_id_t)0xff) {
        s_demo_page = (helm_page_id_t)0xff;
    }

#if MYVENDOR_LVGL_STALL_LOG
    t0 = lv_tick_get();
#endif
    if (helm_save_open()) {
        helm_obj_press(s_sh.save_mask);
        helm_discard_ride();
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        myvendor_sound_back();
        return;
    }

    /* 暂停态：KEY1 短 = 返回环形（记录继续），不再就地继续计时（R1-S4a）。 */
    if (s_sh.paused) {
        printf("helm: KEY1 short (paused) -> back to ring\n");
        helm_back_to_ring();
        return;
    }

    if (helm_flip_busy()) {
        LVGL_STALL("helm_on_prev drop busy");
        return;
    }

    idx = helm_active_idx();
    *idx = (uint8_t)((*idx + n - 1u) % n);
    s_sh.view_dir = -1;
    s_sh.view_anim = true;
    LVGL_STALL("helm_on_prev view=%u/%u riding=%d",
           (unsigned)*idx + 1u, (unsigned)n, helm_riding() ? 1 : 0);
    helm_apply_view();
    helm_flip_arm(helm_riding() ? HELM_FLIP_GUARD_MS : HELM_VIEW_MS);
    helm_nums_defer_begin();
    LVGL_STALL("helm_on_prev done %ums",
        (unsigned)lv_tick_elaps(t0));
}

static void helm_save_clicked(lv_event_t * e)
{
    LV_UNUSED(e);
    /* 第一段右键（保存）：先抓摘要 → 原有入库链（顺序不变）→ 第二段结果卡。 */
    helm_ride_sum_capture();
    printf("helm: save confirm -> keep ride\n");
    helm_finish_ride(true);
    /* 骑行结束 = 记录数变了。菜单那边平时只读缓存（用户 2026-09-26：
     * "开机、骑行结束、进入骑行记录"三处才更新），所以这里显式失效一次。 */
    helm_gpx_count_invalidate();
    helm_save_done_show(true);
}

static void helm_prompt_save(void)
{
    if (s_sh.save_mask) {
        helm_refresh_numbers();
        lv_obj_clear_flag(s_sh.save_mask, LV_OBJ_FLAG_HIDDEN);
        lv_obj_move_foreground(s_sh.save_mask);
        helm_obj_stagger_in(s_sh.save_mask);
        myvendor_sound_prompt();
        printf("helm: save ask shown (paused)\n");
    }
}

/**
 * @brief 骑行/暂停中返回环形主页（R1-S4a）。
 * @details 只切视图，不动记录：`helm_riding()` 仍为 true、`s_sh.paused` 保持原值，
 *          REC 按状态栏既有规则（暂停灰 / 记录红）画。再进骑行由
 *          `helm_ring_enter(0)` / 右键长按清 `at_ring` 并 apply_view。
 */
static void helm_back_to_ring(void)
{
    if (!s_sh.attached) {
        return;
    }

    s_sh.at_ring = true;
    s_sh.view_anim = false;
    helm_apply_view();
    helm_refresh_numbers();
    helm_raise_chrome();
    printf("helm: back to ring ride=%d paused=%d\n",
           helm_riding() ? 1 : 0, s_sh.paused ? 1 : 0);
}

static void helm_on_next(void * ud)
{
    uint8_t n = helm_page_count();
    uint8_t * idx;
#if MYVENDOR_LVGL_STALL_LOG
    uint32_t t0;
#endif

    LV_UNUSED(ud);
    if (!s_sh.attached) {
        LVGL_STALL("helm_on_next drop !attached covered=%d",
            (int)s_sh.ui_covered);
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    /* 第二段结果卡（R1-S4b）：右键 = 关闭并回环形。 */
    if (helm_save_done_active()) {
        helm_save_done_close();
        return;
    }

    /* 环形主页（R1-S2）：短按 = 顺时针转一格，**不翻页**。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY2 short rotate cw (mode=%u)\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_rotate(1);
        return;
    }

    /* 演示页面锁：任意翻页键先解锁，本次按键继续走正常翻页（下面会 apply）。 */
    if (s_demo_page != (helm_page_id_t)0xff) {
        s_demo_page = (helm_page_id_t)0xff;
    }

#if MYVENDOR_LVGL_STALL_LOG
    t0 = lv_tick_get();
#endif
    if (helm_save_open()) {
        helm_obj_press(s_sh.save_mask);
        helm_save_clicked(NULL);
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        return;
    }

    /* 暂停态：KEY2 短 = 询问是否保存（复用现有 save_mask 卡片，外观不变）。 */
    if (s_sh.paused) {
        printf("helm: KEY2 short (paused) -> save ask\n");
        helm_prompt_save();
        return;
    }

    if (helm_flip_busy()) {
        LVGL_STALL("helm_on_next drop busy");
        return;
    }

    idx = helm_active_idx();
    *idx = (uint8_t)((*idx + 1u) % n);
    s_sh.view_dir = 1;
    s_sh.view_anim = true;
    LVGL_STALL("helm_on_next view=%u/%u riding=%d",
           (unsigned)*idx + 1u, (unsigned)n, helm_riding() ? 1 : 0);
    helm_apply_view();
    helm_flip_arm(helm_riding() ? HELM_FLIP_GUARD_MS : HELM_VIEW_MS);
    helm_nums_defer_begin();
    LVGL_STALL("helm_on_next done %ums",
        (unsigned)lv_tick_elaps(t0));
}

static void helm_on_menu(void * ud)
{
    LV_UNUSED(ud);
    if (!s_sh.attached) {
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    /* 第二段结果卡（R1-S4b）：只留「右=关闭」，KEY1 长无动作。 */
    if (helm_save_done_active()) {
        printf("helm: save stage2 open, KEY1 long ignored\n");
        return;
    }

    if (helm_save_open()) {
        printf("helm: save mask closed by KEY1 long\n");
        helm_save_hide();
        myvendor_sound_back();
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        myvendor_sound_back();
        return;
    }

    /* 环形主页（R1-S2）：KEY1 长 = 进入当前模式。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY1 long enter mode=%u\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_enter((int)s_sh.ring_mode);
        return;
    }

    /* R1-S4a：骑行页 KEY1 长 = 返回环形（记录继续）；菜单只能从环形的
     * 「设置」模式进入，这里不再开菜单。暂停态 KEY1 长无动作。 */
    if (s_sh.paused) {
        printf("helm: KEY1 long ignored (paused)\n");
        return;
    }

    printf("helm: KEY1 long (ride page) -> back to ring\n");
    myvendor_sound_back();
    helm_back_to_ring();
}

void helm_shell_toggle_ride(void)
