static void helm_on_rec(void * ud)
{
    LV_UNUSED(ud);

    /* 第二段结果卡（R1-S4b）：右键长按 = 关闭，先于开骑/演示锁。 */
    if (helm_save_done_active()) {
        helm_save_done_close();
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    /* 与翻页键同一语义：真实按键先解锁演示页面锁，否则 began ride 后
     * apply_view 仍会锁在演示页（R1-S2 证据里 KEY2 长按开骑要看到 DATA）。 */
    if (s_demo_page != (helm_page_id_t)0xff) {
        s_demo_page = (helm_page_id_t)0xff;
    }
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY2 long ride start/continue\n");
    }
    helm_shell_toggle_ride();
}

