/**
 * @brief 演示：在页面回调边界注入 KEY（仅调试；不经过按键状态机）。
 * @details R1-S4b：休眠中**只唤醒并吞掉本次输入**，与板端
 *          `lv_port_btn_timer()` 的 `helm_idle_is_sleeping()` 分支同一顺序
 *          （模拟器里 lv_port_buttons.c 整份被 `#if __NuttX__` 关掉，只能在这里复现）。
 */
void helm_shell_demo_key(int key, bool long_press)
{
    if (!s_sh.attached) {
        printf("helm: demo key KEY%d ignored (not attached)\n", key);
        return;
    }

    if (helm_idle_is_sleeping()) {
        printf("helm: wake (KEY%d swallowed)\n", key);
        helm_idle_wake();
        return;
    }

    printf("helm: demo key KEY%d %s\n", key, long_press ? "long" : "short");
    if (key == 1) {
        if (long_press) {
            helm_on_menu(NULL);
        } else {
            helm_on_prev(NULL);
        }
    } else if (key == 2) {
        if (long_press) {
            helm_on_rec(NULL);
        } else {
            helm_on_next(NULL);
        }
    }
}

