 * 骑行页 2：数字方阵（HELM_PAGE_DATA_ALL，WP-HELM10/R1-S3a）
 *
 * 2 列 × 4 行、卡片 104×64（x=12/124，y=16/84/152/220），8 格：
 * 时速/均速/里程/时间/心率/踏频/海拔/坡度。每格 = 12px 标签 + 22px 数值
 * （时速 32px）+ 12px 单位；数值在 62px 定宽盒里右对齐、单位固定 x=68
 * （数字字体等宽 ⇒ 两列严格对齐）。暂停时数值退 TRACK、单位保持 MUTE。
 * ═══════════════════════════════════════════════════════════════════════════ */

/** @brief 每格左侧 3px 身份条：速度绿 / 时间·踏频橙 / 心率红 / 海拔·坡度青。 */
static uint32_t s_grid_ink[8];

/** @brief 数字方阵刷值（500 ms UI 节拍）。 */
static void helm_grid_tick(const bicycle_runtime_t * rt)
{
    const uint32_t ink = s_sh.paused ? HELM_COLOR_TRACK : HELM_COLOR_INK;
    char b[8][24];
    char tmp[16];
    int i;

    helm_fmt_speed(b[0], sizeof(b[0]), rt ? rt->speed_kph : 0.0f);
    helm_fmt_speed(b[1], sizeof(b[1]), helm_session_avg_kph(rt));
    helm_fmt_km(b[2], sizeof(b[2]),
                rt ? (float)(rt->session_distance_m / 1000.0) : 0.0f);
    helm_fmt_time(b[3], sizeof(b[3]), rt ? rt->session_elapsed_ms : 0ull);
    lv_snprintf(b[4], sizeof(b[4]), "%s",
        helm_dash(rt != NULL && rt->hr_valid, tmp, sizeof(tmp), "%u",
                  rt ? (unsigned)rt->hr_bpm : 0u));
    lv_snprintf(b[5], sizeof(b[5]), "%s",
        helm_dash(rt != NULL && rt->cadence_valid, tmp, sizeof(tmp), "%u",
                  rt ? (unsigned)rt->cadence_rpm : 0u));
    if (rt != NULL && rt->has_altitude) {
        lv_snprintf(b[6], sizeof(b[6]), "%d", (int)(rt->altitude_m + 0.5f));
    } else {
        lv_snprintf(b[6], sizeof(b[6]), "--");
    }
    lv_snprintf(b[7], sizeof(b[7]), "%+.1f", rt ? rt->grade_pct : 0.0f);

    for (i = 0; i < 8; i++) {
        helm_label_set(s_sh.grid_val[i], b[i]);
        helm_set_text_hex(s_sh.grid_val[i], ink);
    }

    /* 30px TTF 可能比本页晚就绪（系统字体预载）：到了就换上去，换不到就保持
     * 建页时的 22px 点阵回退（工厂固件本来就没有 TTF）。 */
    if (s_sh.grid_val[0] != NULL) {
        const lv_font_t * f30 = helm_font_sys(30, s_sh.font_val);

        if (f30 != NULL &&
            lv_obj_get_style_text_font(s_sh.grid_val[0], 0) != f30) {
            lv_obj_set_style_text_font(s_sh.grid_val[0], f30, 0);
            lv_obj_set_style_text_letter_space(s_sh.grid_val[0], 0, 0);
        }
    }
}

/** @brief 转向箭头字形 → 动作词（与导航横幅同一张映射表，别自造新词）。 */
static const char * helm_map_card_turn_act(const char * ico)
{
    if (ico == NULL) {
        return "导航中";
    }
    if (strcmp(ico, "←") == 0) {
        return "左转";
    }
    if (strcmp(ico, "→") == 0) {
        return "右转";
    }
    if (strcmp(ico, "U") == 0) {
        return "掉头";
    }
    if (strcmp(ico, "●") == 0) {
        return "已到达";
    }
    return "直行";
}

