/** @brief 把剖面画布挂到（可能刚重建的）画布对象上；失败返回 false。 */
static bool helm_dial_canvas_attach(lv_obj_t * cv)
{
    if (cv == NULL) {
        return false;
    }
    if (s_dial_cbuf == NULL) {
        s_dial_cbuf = vmap_malloc((size_t)HELM_DIAL_ELEV_W *
                                  (size_t)HELM_DIAL_ELEV_H * 2u);
    }
    if (s_dial_cbuf == NULL) {
        lv_obj_add_flag(cv, LV_OBJ_FLAG_HIDDEN);
        return false;
    }
    lv_canvas_set_buffer(cv, s_dial_cbuf, HELM_DIAL_ELEV_W,
                         HELM_DIAL_ELEV_H, LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(cv, HELM_DIAL_ELEV_W, HELM_DIAL_ELEV_H);
    return true;
}

/** @brief 剖面重绘：逐段三角填到基线 + 2px 脊线（复用 CLIMB 页那套画法/配色）。 */
static void helm_dial_elev_paint(void)
{
    lv_obj_t * cv = s_sh.dial_elev_cv;
    lv_layer_t layer;
    const int base = HELM_DIAL_ELEV_H - 1;
    const int top = 3;
    const int bot = base - top;
    int span = s_dial_mx - s_dial_mn;
    uint32_t i;

    if (cv == NULL || s_dial_cbuf == NULL || s_dial_n < 2u) {
        return;
    }
    if (span < 1) {
        span = 1;
    }

    lv_canvas_fill_bg(cv, helm_color(HELM_COLOR_PAPER), LV_OPA_COVER);
    lv_canvas_init_layer(cv, &layer);
    for (i = 0; i + 1u < s_dial_n; i++) {
        const int x1 = (int)((i * (uint32_t)(HELM_DIAL_ELEV_W - 1)) /
                             (uint32_t)(s_dial_n - 1u));
        const int x2 = (int)(((i + 1u) * (uint32_t)(HELM_DIAL_ELEV_W - 1)) /
                             (uint32_t)(s_dial_n - 1u));
        const int y1 = bot -
            (int)(((int32_t)s_dial_eles[i] - s_dial_mn) * (bot - top)) / span;
        const int y2 = bot -
            (int)(((int32_t)s_dial_eles[i + 1u] - s_dial_mn) * (bot - top)) / span;
        lv_point_precise_t p1;
        lv_point_precise_t p2;

        p1.x = x1;
        p1.y = y1;
        p2.x = x2;
        p2.y = y2;
        helm_climb_paint_seg(&layer, p1, p2, base,
            helm_color_snap(helm_climb_zone_fill(s_dial_zone[i])),
            helm_color(helm_climb_zone_ink(s_dial_zone[i])), 2);
    }
    lv_canvas_finish_layer(cv, &layer);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_HIDDEN);
    lv_obj_invalidate(cv);
}

/**
 * @brief 剖面取数（导航优先，否则用记录采样）+ 指纹变化时重绘。
 * @note 与 `helm_climb_profile_reload()` 同一数据源、同一画法，但不碰 CLIMB
 *       页的 chart/烘焙状态（本页 500 ms 一拍，不能每次重烘大画布）。
 */
static void helm_dial_elev_tick(const bicycle_runtime_t * rt)
{
    uint32_t n = 0;
    uint32_t step_cm = 1;
    uint32_t pts = 0;
    uint32_t cm = 0;
    bool nav = helm_nav_on();
    bool changed = false;
    bool have = false;
    int16_t last = 0;
    uint32_t i;

    if (nav) {
        uint32_t cur = 0;

        n = map_page_nav_profile_ele(s_sh.map, s_dial_eles,
                                     HELM_CLIMB_PROF_N, &cur);
        (void)map_page_nav_progress(s_sh.map, &pts, &cm, NULL, n);
        if (n >= 2u) {
            changed = (n != s_dial_fp_n || pts != s_dial_fp_pts ||
                       cm != s_dial_fp_cm || !s_dial_fp_nav);
            step_cm = (cm > 0u) ? (cm / (n - 1u)) : 0u;
            if (step_cm < 1u) {
                step_cm = 1u;
            }
        }
        s_dial_fp_nav = true;
        s_dial_fp_pts = pts;
        s_dial_fp_cm = cm;
    } else if (helm_riding() && s_rec_ele_n >= 2u) {
        n = s_rec_ele_n;
        memcpy(s_dial_eles, s_rec_ele, (size_t)n * sizeof(s_dial_eles[0]));
        changed = (n != s_dial_fp_n || s_dial_fp_nav ||
                   s_rec_ele_slot != s_dial_fp_slot);
        if (rt != NULL && n >= 2u) {
            double d = rt->session_distance_m * 100.0 / (double)(n - 1u);

            step_cm = (d > 0.0) ? (uint32_t)d : 1u;
            if (step_cm < 1u) {
                step_cm = 1u;
            }
        }
        s_dial_fp_nav = false;
        s_dial_fp_slot = s_rec_ele_slot;
    }
    s_dial_fp_n = (uint8_t)n;

    if (n < 2u) {
        s_dial_n = 0;
        if (s_sh.dial_elev_cv != NULL) {
            lv_obj_add_flag(s_sh.dial_elev_cv, LV_OBJ_FLAG_HIDDEN);
        }
        return;
    }

    if (!changed && s_dial_n >= 2u) {
        return;
    }

    /* UNKNOWN 用前值填平（与 CLIMB 页同一规则）；整条都无值就不画。 */
    for (i = 0; i < n; i++) {
        if (s_dial_eles[i] != (int16_t)VGRF_ELE_UNKNOWN) {
            last = s_dial_eles[i];
            have = true;
            break;
        }
    }
    if (!have) {
        s_dial_n = 0;
        if (s_sh.dial_elev_cv != NULL) {
            lv_obj_add_flag(s_sh.dial_elev_cv, LV_OBJ_FLAG_HIDDEN);
        }
        return;
    }
    for (i = 0; i < n; i++) {
        if (s_dial_eles[i] == (int16_t)VGRF_ELE_UNKNOWN) {
            s_dial_eles[i] = last;
        } else {
            last = s_dial_eles[i];
        }
    }
    for (i = 0; i + 1u < n; i++) {
        s_dial_zone[i] = helm_climb_grade_zone(s_dial_eles[i],
            s_dial_eles[i + 1u], step_cm);
    }

    helm_climb_axis(s_dial_eles, n, &s_dial_mn, &s_dial_mx);
    s_dial_n = (uint8_t)n;
    helm_dial_elev_paint();
}

