/**
 * @brief KEY2 长按 = 确定 / 激活当前行（R1-S4a 键位表；原 KEY2 短按的动作）。
 * @details 绝大多数屏幕等价于原来的 `helm_on_confirm()`（开子页 / 执行行动 /
 *          开关行 toggle）。少数屏幕的"激活"本来就是旧的长按语义，继续走旧长按：
 *            · 手机蓝牙：选中已绑定手机 → 弹「解除绑定？」（该行没有别的动作）；
 *            · 坐标点详情：长按 = 行动菜单（左右键只翻点位）；
 *            · 常用点：未选中行 = 选中（旧短按）；已选中行 = 开始导航（旧长按）；
 *            · 扫描结果：正在连接时长按 = 取消连接。
 *          R1-S4b 行内补偿：
 *            · 蓝牙设备（SENSORS）：已连上的传感器行 → 断开；未连接 → 进配对页；
 *            · 扫描结果（SCAN）：选中行是**当前已连接**的记录设备 → 弹「忘记设备？」。
 *          记录列表的"长按删除"快捷方式退役：删除仍在骑行详情页的「删除」行，
 *          长按确认。
 */
static void helm_on_ok(void * ud)
{
    helm_menu_t * m = s_menu;
    helm_scr_t scr;

    if (m == NULL) {
        return;
    }

    scr = helm_cur_scr(m);

    if (scr == HELM_SCR_PHONE) {
        uint8_t * sel = helm_cur_sel(m);
        unsigned nphone = myvendor_devctl_pair_phone_count();

        if (!s_phone_pair_arm && !s_phone_unbind_arm &&
            sel != NULL && *sel < nphone) {
            helm_on_key2_long(ud);
            return;
        }
        helm_on_confirm(ud);
        return;
    }

    if (scr == HELM_SCR_SENSORS) {
        /* R1-S4b：按行状态分流（断开 / 进配对页），见 helm_on_key2_long。 */
        helm_on_key2_long(ud);
        return;
    }

    if (scr == HELM_SCR_SCAN && helm_scan_sel_linked(m)) {
        /* R1-S4b：已连接的记录设备上，确定 = 忘记（弹确认 dock）。 */
        printf("helm: scan KEY2 long -> forget ask (linked row)\n");
        helm_on_key2_long(ud);
        return;
    }

    if (scr == HELM_SCR_NAVPT_DETAIL) {
        helm_on_key2_long(ud);
        return;
    }

    if (scr == HELM_SCR_FAVS) {
        uint8_t * sel;
        uint8_t idx;
        uint8_t i;
        bool picked = false;

        if (helm_fill_items(m)) {
            helm_menu_squash_abort();
            return;
        }
        sel = helm_cur_sel(m);
        if (sel != NULL && *sel < m->count) {
            idx = m->items[*sel].extra;
            for (i = 0u; i < m->fav_order_n; i++) {
                if (m->fav_order[i] == idx) {
                    picked = true;
                    break;
                }
            }
        }
        if (picked) {
            helm_on_key2_long(ud);   /* 已选：开始导航（旧长按动作） */
        } else {
            helm_on_confirm(ud);     /* 未选：加入/移出路线（旧短按动作） */
        }
        return;
    }

    if (scr == HELM_SCR_SCAN_PICK && s_scan_link_wait) {
        helm_on_key2_long(ud);       /* 连接中：取消 */
        return;
    }

    helm_on_confirm(ud);
}

static void helm_bind_keys(void)
{
    /* R1-S4a 键位表（所有子页继承）：
     *   KEY1 短 = 上移；KEY2 短 = 下移；KEY1 长 = 返回；KEY2 长 = 确定/激活。
     * KEY1 双击已注销：短按就是上移，不能再有 350 ms 的延后窗口。 */
