int helm_menu_open(void)
{
    int rc;

    if (lvgl_page_current_id() == BICYCLE_PM_ID_MENU) {
        return 0;
    }

    /* lv_pm_open_page_msg preempts an in-flight transition; do not refuse. */
    rc = lv_pm_open_page_msg((lv_pm_id)BICYCLE_PM_ID_MENU, NULL);
    printf("helm: menu open rc=%d\n", rc);
    return rc;
}

/**
 * @brief 打开菜单并停在主菜单根页第 root_row 行（环形主页的模式出口）。
 * @details 行号是 P_ROOT[] 的数据行序号（0 基）：导航=0、骑行记录=4、设置=6。
 *          导航/回放中主菜单顶部还有动态动作组，`helm_root_jump_apply()`
 *          会按 P_ROOT_NAV / P_ROOT_GPX 的行数加偏移。若菜单已在当前页，
 *          立即回到根页并落行；否则挂到 will_appear 的首帧。
 */
int helm_menu_open_at(int root_row)
{
    int rc;

    if (root_row < 0) {
        root_row = 0;
    }
    s_root_jump = root_row;
    rc = helm_menu_open();
    if (rc != 0) {
        s_root_jump = -1;
        return rc;
    }

    /* 已在菜单页：helm_menu_open() 直接返回 0，不会再有 will_appear。 */
    if (lvgl_page_current_id() == BICYCLE_PM_ID_MENU && s_menu != NULL) {
        helm_root_jump_apply(s_menu);
        helm_menu_paint(s_menu);
    }
    return 0;
}

void helm_menu_refresh(void)
{
    if (s_menu != NULL) {
        helm_menu_paint(s_menu);
    }
}

