    helm_autopause_hold_clear();
    map_page_set_recording(s_sh.map, true);
    /* 已在导航中则留在当前骑行页，勿被待机页索引带跑。 */
    if (!helm_nav_on()) {
        /* 待机 → 骑行：待机 3 页 [主页面, 表盘, 数字方阵]、
         * 骑行 3 页 [表盘, 数字方阵, 地图] ⇒
         * 主页面/表盘都落到表盘[0]，数字方阵落到[1]。 */
        s_sh.ride_idx = (s_sh.home_idx >= 2u) ? 1u : 0u;
    }
    helm_apply_view();
    helm_refresh_numbers();
    myvendor_sound_ride();
}

