static void helm_ring_dump_ink(const char * name, lv_obj_t * obj)
{
    const lv_font_t * font;
    lv_point_t sz;
    const char * txt;

    if (obj == NULL) {
        printf("[ring] ink %s=null\n", name);
        return;
    }
    font = lv_obj_get_style_text_font(obj, 0);
    txt = lv_label_get_text(obj);
    if (font == NULL || txt == NULL) {
        printf("[ring] ink %s=0x0\n", name);
        return;
    }
    lv_text_get_size(&sz, txt, font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    printf("[ring] ink %s=%dx%d\n", name, (int)sz.x, (int)sz.y);
}

