 */
static void helm_ring_rotate(int dir)
{
    int from;
    int to;
    int32_t a0;
    int32_t target;
    uint8_t slot;
    uint8_t nslot;
    lv_anim_t a;

    if (!s_sh.attached || s_sh.ring == NULL ||
        s_sh.view_id != HELM_PAGE_RING) {
        return;
    }
    if (s_sh.ring_busy) {
        printf("helm: ring rotate busy, drop\n");
        return;
    }
    if (dir == 0) {
        dir = 1;
    }

    from = s_sh.ring_mode & 3;
    to = (from + ((dir > 0) ? 1 : 3)) & 3;
    a0 = s_sh.ring_angle;
    target = (int32_t)to * 90;
    if (dir > 0) {
        while (target <= a0) {
            target += 360;
        }
    } else {
        while (target >= a0) {
            target -= 360;
        }
    }

    slot = s_ring_slot;
    nslot = (uint8_t)(slot ^ 1u);
    if (s_sh.ring_fill[nslot] != NULL) {
        lv_obj_delete(s_sh.ring_fill[nslot]);
        s_sh.ring_fill[nslot] = NULL;
