static void helm_ring_set_font(lv_obj_t * obj, const lv_font_t * font)
{
    if (obj != NULL && font != NULL &&
        lv_obj_get_style_text_font(obj, 0) != font) {
        lv_obj_set_style_text_font(obj, font, 0);
    }
}

static void helm_ring_set_arc_opa(lv_obj_t * arc, int opa)
{
    if (arc == NULL) {
        return;
    }
    if (opa < 0) {
        opa = 0;
    } else if (opa > 255) {
        opa = 255;
    }
    lv_obj_set_style_arc_opa(arc, (lv_opa_t)opa, LV_PART_INDICATOR);
}

