static void helm_on_prev(void * ud)
{
    uint8_t n = helm_page_count();
    uint8_t * idx;
#if MYVENDOR_LVGL_STALL_LOG
    uint32_t t0;
#endif

    LV_UNUSED(ud);
    if (!s_sh.attached) {
        LVGL_STALL("helm_on_prev drop !attached covered=%d",
            (int)s_sh.ui_covered);
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    /* 第二段结果卡（R1-S4b）：只留「右=关闭」，左键无动作。 */
    if (helm_save_done_active()) {
        printf("helm: save stage2 open, KEY1 short ignored\n");
        return;
    }

    /* 环形主页（R1-S2）：短按 = 逆时针转一格，**不翻页**（旧页留给 S3 再摘）。
     * 必须在演示锁解锁之前分流：环形页的演示态也要能连续转。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY1 short rotate ccw (mode=%u)\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_rotate(-1);
        return;
    }

    /* 演示页面锁：任意翻页键先解锁，本次按键继续走正常翻页（下面会 apply）。 */
    if (s_demo_page != (helm_page_id_t)0xff) {
        s_demo_page = (helm_page_id_t)0xff;
    }

#if MYVENDOR_LVGL_STALL_LOG
    t0 = lv_tick_get();
#endif
    if (helm_save_open()) {
        helm_obj_press(s_sh.save_mask);
        helm_discard_ride();
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        myvendor_sound_back();
        return;
    }

    /* 暂停态：KEY1 短 = 返回环形（记录继续），不再就地继续计时（R1-S4a）。 */
    if (s_sh.paused) {
        printf("helm: KEY1 short (paused) -> back to ring\n");
        helm_back_to_ring();
        return;
    }

    if (helm_flip_busy()) {
        LVGL_STALL("helm_on_prev drop busy");
        return;
    }

    idx = helm_active_idx();
    *idx = (uint8_t)((*idx + n - 1u) % n);
    s_sh.view_dir = -1;
    s_sh.view_anim = true;
    LVGL_STALL("helm_on_prev view=%u/%u riding=%d",
           (unsigned)*idx + 1u, (unsigned)n, helm_riding() ? 1 : 0);
    helm_apply_view();
    helm_flip_arm(helm_riding() ? HELM_FLIP_GUARD_MS : HELM_VIEW_MS);
    helm_nums_defer_begin();
    LVGL_STALL("helm_on_prev done %ums",
        (unsigned)lv_tick_elaps(t0));
}

