{"file_path": "/home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/my_vendor/ui/bicycle/src/lvgl_page/helm_shell.c", "new_string": "/**
 * @brief 底部走势画布：无海拔剖面时画实时速度 sparkline（R1-S6）。
 * @details 数据用现有 `s_hist[HELM_HIST_SPEED]`（UI tick 里的 `helm_hist_push()`
 *          每秒维护），不另建历史；画布与海拔剖面共用（两者互斥）。
 *          历史 <2 点（刚开骑）：画一条水平基线，绝不空白。
 */
static void helm_dial_speed_paint(const bicycle_runtime_t * rt)
{
    lv_obj_t * cv = s_sh.dial_elev_cv;
    lv_layer_t layer;
    const int w = HELM_DIAL_ELEV_W;
    const int h = HELM_DIAL_ELEV_H;
    int n = (int)s_hist_n;

    if (cv == NULL || s_dial_cbuf == NULL) {
        return;
    }

    lv_canvas_fill_bg(cv, helm_color(HELM_COLOR_PAPER), LV_OPA_COVER);
    lv_canvas_init_layer(cv, &layer);

    if (n >= 2 && s_hist != NULL) {
        float mn = s_hist[HELM_HIST_SPEED][0];
        float mx = mn;
        int i;
        int py = h / 2;

        for (i = 1; i < n; i++) {
            const float v = s_hist[HELM_HIST_SPEED][i];

            if (v < mn) {
                mn = v;
            }
            if (v > mx) {
                mx = v;
            }
        }
        if (mx - mn < 1.0f) {
            mx = mn + 1.0f;
        }

        for (i = 0; i + 1 < n; i++) {
            const int x1 = (i * (w - 1)) / (n - 1);
            const int x2 = ((i + 1) * (w - 1)) / (n - 1);
            const int y1 = (h - 3) -
                (int)(((s_hist[HELM_HIST_SPEED][i] - mn) * (float)(h - 6)) /
                      (mx - mn));
            const int y2 = (h - 3) -
                (int)(((s_hist[HELM_HIST_SPEED][i + 1] - mn) *
                       (float)(h - 6)) / (mx - mn));
            lv_draw_line_dsc_t ld;

            lv_draw_line_dsc_init(&ld);
            ld.color = helm_color(HELM_COLOR_INK);
            ld.width = 1;
            ld.opa = LV_OPA_COVER;
            ld.p1.x = x1;
            ld.p1.y = y1;
            ld.p2.x = x2;
            ld.p2.y = y2;
            lv_draw_line(&layer, &ld);
        }

        py = (h - 3) -
            (int)(((s_hist[HELM_HIST_SPEED][n - 1] - mn) * (float)(h - 6)) /
                  (mx - mn));
        {
            lv_draw_rect_dsc_t rd;
            lv_area_t a;

            lv_draw_rect_dsc_init(&rd);
            rd.bg_color = helm_color(HELM_COLOR_INK);
            rd.bg_opa = LV_OPA_COVER;
            rd.radius = 1;
            a.x1 = w - 2;
            a.y1 = py - 1;
            a.x2 = w - 1;
            a.y2 = py;
            lv_draw_rect(&layer, &rd, &a);
        }
    } else {
        lv_draw_rect_dsc_t rd;
        lv_area_t a;

        lv_draw_rect_dsc_init(&rd);
        rd.bg_color = helm_color(HELM_COLOR_MUTE);
        rd.bg_opa = LV_OPA_COVER;
        a.x1 = 0;
        a.y1 = h - 6;
        a.x2 = w - 1;
        a.y2 = h - 6;
        lv_draw_rect(&layer, &rd, &a);
    }

    lv_canvas_finish_layer(cv, &layer);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_HIDDEN);

    if (s_sh.dial_spd_val != NULL) {
        char sp[24];

        helm_fmt_speed(sp, sizeof(sp), rt ? rt->speed_kph : 0.0f);
        lv_snprintf(sp + strlen(sp), sizeof(sp) - strlen(sp), " km/h");
        helm_label_set(s_sh.dial_spd_val, sp);
    }
}

/**
 * @brief 底部区域二选一：有海拔剖面 → 剖面 + 「前方 2 km」；
 *        否则 → 速度走势 + 「速度 / X.X km/h」。
 */
static void helm_dial_bottom_tick(const bicycle_runtime_t * rt)
{
    const bool alt = (s_dial_n >= 2u);

    helm_show(s_sh.dial_elev_line, alt);
    helm_show(s_sh.dial_elev_lab, alt);
    helm_show(s_sh.dial_elev_cur, alt);
    helm_show(s_sh.dial_spd_lab, !alt);
    helm_show(s_sh.dial_spd_val, !alt);

    if (alt) {
        return;
    }

    helm_dial_speed_paint(rt);
}

